#!/usr/bin/env python3
"""Build a local review entry point from immutable round manifests and reviews."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
rounds = []
for number in range(30, 35):
    folder = ROOT / f'rounds/r{number}'
    if not (folder / 'manifest.json').exists():
        continue
    report = folder / 'reports/independent-evaluation.json'
    value = json.loads(report.read_text()) if report.exists() else {}
    rounds.append({'number': number, 'status': value.get('status', '评审中'),
                   'mean': value.get('mean_score_100'), 'platforms': value.get('platforms', {}),
                   'changes': json.loads((folder / 'changes.json').read_text())['changes']})
(ROOT / 'review-summary.json').write_text(json.dumps(rounds, ensure_ascii=False, indent=2) + '\n')
template = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mote · 三端 UI 评审</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f6f4ef;color:#292722;font:15px/1.7 system-ui,-apple-system,"Noto Sans SC",sans-serif}button,select{font:inherit}a{color:#70529b;text-decoration:none}a:hover{text-decoration:underline}button,select{border:1px solid #d9d4ca;border-radius:8px;background:#fffdfa;padding:9px 14px;color:inherit}button{cursor:pointer}button[aria-pressed=true]{background:#302c27;color:white;border-color:#302c27}header{max-width:1680px;margin:auto;padding:32px 30px 20px}.eyebrow{font-size:12px;letter-spacing:.08em;color:#777164}h1{font-size:30px;margin:8px 0}header p{color:#70695d;max-width:850px;margin:8px 0}.toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:20px;margin-top:24px}.toolbar label{display:grid;gap:5px;font-size:12px;color:#6c655c}.toolbar select{min-width:150px;font-size:14px}.platforms{display:flex;flex-wrap:wrap;gap:7px}main{max-width:1680px;margin:auto;padding:0 30px 50px}.summary{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-top:1px solid #ddd8cf;padding:18px 0}.summary strong{font-size:19px}.summary small{display:block;color:#766e64}.summary-links{display:flex;gap:18px;align-items:center;flex-wrap:wrap}.screens{display:grid;grid-template-columns:1fr 1fr 340px;gap:18px;align-items:start}.screen{min-width:0;border:1px solid #dad4c9;border-radius:12px;background:#fffdf9;overflow:hidden}.screen-head{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid #e1dcd3}.screen-head strong{font-size:14px}.screen-head a{font-size:12px}.viewport{position:relative;overflow:hidden;background:#f9f8f5;min-height:200px}.viewport iframe{position:absolute;left:0;top:0;border:0;transform-origin:0 0;background:#faf9f5}.screens.single{display:flex;justify-content:center}.screens.single .screen{width:100%}.screens.single .screen[data-platform=android]{max-width:430px}.screens.single .screen:not([data-platform=android]){max-width:1440px}.review{margin-top:32px;border-top:1px solid #d8d2c8;padding-top:20px}.review h2{font-size:20px}.review p,.note{color:#71695f}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:13px 16px;text-align:left;border-bottom:1px solid #e0dbd2;white-space:nowrap}th{font-weight:500;color:#70685b}tr.current{background:#ebe7df}details{margin-top:18px}summary{cursor:pointer;font-weight:600}.changes{padding-left:24px;max-width:1000px}.changes li{margin:10px 0}footer{font-size:12px;color:#827a70;padding-top:25px}.weight{display:flex;flex-wrap:wrap;gap:8px 22px;font-size:13px}.weight span{color:#736a5e}.mobile-hint{display:none}@media(max-width:1150px){.screens{grid-template-columns:1fr 1fr}.screen[data-platform=android]{grid-column:1/-1;width:390px;justify-self:center}}@media(max-width:700px){header,main{padding-left:18px;padding-right:18px}h1{font-size:25px}.screens{grid-template-columns:1fr}.screen[data-platform=android]{grid-column:auto;max-width:100%;width:390px}.toolbar{gap:12px}.toolbar select{min-width:130px}.summary{gap:10px}.mobile-hint{display:block}}
</style></head><body>
<header><span class="eyebrow">MOTE / UI REVIEW</span><h1>三个端，每一轮都能回看。</h1><p>按独立功能清单检查“用户能找到什么、如何完成、结果是否讲清楚”。这里保留 R30–R34 的 HTML 原型与独立评分。</p>
<div class="toolbar"><label>迭代版本<select id="round"></select></label><label>演示内容<select id="scene"><option value="first">新用户第一眼</option><option value="library">已有资料的资料库</option><option value="import">导入与资料说明</option><option value="sources">来源与采集职责</option><option value="ask">问一问</option><option value="todos">待办与日程</option><option value="settings">设置</option></select></label><div class="platforms" aria-label="查看哪一端"><button data-view="all" aria-pressed="true">三端并排</button><button data-view="web" aria-pressed="false">Web</button><button data-view="mac" aria-pressed="false">Mac</button><button data-view="android" aria-pressed="false">Android</button></div></div>
<p class="note" style="font-size:12px">切换版本或场景会重置该演示。页面可以点击；“单独打开”可按完整尺寸查看。</p></header>
<main><div class="summary"><div><strong id="summary-title"></strong><small id="summary-caption"></small></div><div class="summary-links"><a id="branch" target="_blank" rel="noreferrer">独立 Git 分支 ↗</a><a id="report">独立评审报告</a><a href="contract/user-features.md">188 项功能清单</a></div></div><section class="screens" id="screens" aria-label="三端交互原型"></section>
<section class="review"><h2>同一套标准，逐轮比较</h2><div class="weight"><span>新用户友好度 25%</span><span>功能完整性 20%</span><span>简洁与注意力 20%</span><span>逻辑清晰 15%</span><span>设计 10%</span><span>工艺 5%</span><span>原创性 5%</span></div><p>均分提高不代表完整性验收通过。部分完成、尚未验证以及门槛未通过的项目都保留在各轮报告里。</p><div class="table-wrap"><table><thead><tr><th>轮次</th><th>Web</th><th>Mac</th><th>Android</th><th>均分 / 100</th><th>独立验收</th></tr></thead><tbody id="score-rows"></tbody></table></div><details><summary>这一轮具体改了什么</summary><ol class="changes" id="changes"></ol></details><footer>验证范围：HTML 界面与合成数据。没有执行原生应用、真实模型、后台服务、OAuth、真实采集、日历写入或设备配对。功能清单、评分规则与每轮原型身份分别冻结保存。</footer></section></main>
<script>
const rounds=__ROUNDS__,labels={web:'Web · 中央资料库',mac:'Mac · 本机采集与资料库',android:'Android · 随身记录与资料库'},sizes={web:[1440,1000],mac:[1440,1000],android:[390,844]};
let selected=rounds.at(-1).number,view='all';
const $=id=>document.getElementById(id),fmt=x=>x==null?'—':Number(x).toFixed(2);
$('round').innerHTML=rounds.map(r=>'<option value="'+r.number+'">R'+r.number+'</option>').join('');$('round').value=selected;
function src(platform){const scene=$('scene').value,route={first:'library',library:'library',import:'import',sources:'sources',ask:'ask',todos:'todos/schedule',settings:'settings'}[scene];return'rounds/r'+selected+'/'+platform+'.html?reset=1&state='+(scene==='first'||scene==='import'?'empty':'populated')+'#/'+route;}
function fit(){document.querySelectorAll('.viewport').forEach(box=>{const [w,h]=sizes[box.dataset.platform],factor=Math.min(1,box.clientWidth/w),frame=box.querySelector('iframe');frame.style.width=w+'px';frame.style.height=h+'px';frame.style.transform='scale('+factor+')';box.style.height=Math.ceil(h*factor)+'px';});}
function show(){const row=rounds.find(r=>r.number===selected);$('summary-title').textContent='R'+selected+' · 独立均分 '+fmt(row.mean);$('summary-caption').textContent=row.status==='FAIL'?'本轮未通过全部验收门槛；具体缺口见报告。':row.status==='PASS'?'本轮达到已冻结的 UI 验收门槛。':'独立评审尚未冻结。';$('branch').href='https://github.com/utopiafar/mote/tree/codex/mote-ui-r'+selected+'-20261022';$('report').href='rounds/r'+selected+'/reports/independent-evaluation.md';$('screens').className='screens'+(view==='all'?'':' single');$('screens').innerHTML=(view==='all'?['web','mac','android']:[view]).map(p=>'<article class="screen" data-platform="'+p+'"><div class="screen-head"><strong>'+labels[p]+'</strong><a href="'+src(p)+'" target="_blank">单独打开 ↗</a></div><div class="viewport" data-platform="'+p+'"><iframe title="R'+selected+' '+labels[p]+'" src="'+src(p)+'"></iframe></div></article>').join('');$('score-rows').innerHTML=rounds.map(r=>'<tr class="'+(r.number===selected?'current':'')+'"><td>R'+r.number+'</td>'+['web','mac','android'].map(p=>'<td>'+fmt(r.platforms[p]?.weighted_score_100)+'</td>').join('')+'<td>'+fmt(r.mean)+'</td><td>'+(r.status==='FAIL'?'未通过全部门槛':r.status==='PASS'?'通过':'评审中')+'</td></tr>').join('');$('changes').replaceChildren(...row.changes.map(c=>{const li=document.createElement('li');li.textContent=c.change;return li;}));fit();}
$('round').addEventListener('change',()=>{selected=Number($('round').value);show();});$('scene').addEventListener('change',show);document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b===button));show();}));window.addEventListener('resize',fit);show();
</script></body></html>'''
(ROOT / 'index.html').write_text(template.replace('__ROUNDS__', json.dumps(rounds, ensure_ascii=False).replace('</', '<\\/')))
print(json.dumps({'rounds': [r['number'] for r in rounds], 'entry': str(ROOT / 'index.html')}))
